/* Partner adjustment preview. No financial requests are sent by this adapter. */
(function () {
    'use strict';
    var IS_PREVIEW = !!document.querySelector('script[src="assets/preview-only.js"]'); // Keep financial submission disabled without a backend integration.
    var MAX_SCREENSHOTS = 6; // Maximum screenshots per adjustment draft.
    var MAX_SCREENSHOT_BYTES = 5 * 1024 * 1024; // Maximum size of one image, in bytes.
    var ALLOWED_AMOUNTS = ['-20.00', '-15.00', '-10.00', '-5.00', '-3.00', '-2.00', '-1.00', '0.00', '1.00', '2.00', '3.00', '5.00', '10.00', '15.00', '20.00'];

    function initReward() {
        var modal = document.getElementById('partnerRewardModal');
        if (!modal || modal.dataset.rewardBound) return;
        modal.dataset.rewardBound = 'true';
        var form = document.getElementById('partnerRewardForm');
        var partner = document.getElementById('partnerRewardPartner');
        var amount = document.getElementById('partnerRewardAmount');
        var positive = document.getElementById('partnerRewardPositive');
        var negative = document.getElementById('partnerRewardNegative');
        var warning = document.getElementById('partnerRewardWarning');
        var reason = document.getElementById('partnerRewardReason');
        var filesInput = document.getElementById('partnerRewardFiles');
        var attachments = document.getElementById('partnerRewardAttachments');
        var apply = document.getElementById('partnerRewardApply');
        var images = [];
        apply.disabled = !IS_PREVIEW;
        apply.title = IS_PREVIEW ? 'Проверить черновик без изменения баланса' : 'Серверное право корректировки не подтверждено';
        function notify(message) {
            document.dispatchEvent(new CustomEvent('admin:previewnotice', { detail: { message: message } }));
        }
        function reset() {
            form.reset();
            syncAmount();
            reason.setCustomValidity('');
            images = [];
            attachments.replaceChildren();
        }
        function syncAmount(source) {
            if (source === positive && positive.value !== '') { negative.value = ''; warning.checked = false; }
            if (source === negative && negative.value !== '') { positive.value = ''; warning.checked = false; }
            if (source === warning && warning.checked) { positive.value = ''; negative.value = ''; }
            amount.value = warning.checked ? '0.00' : positive.value || negative.value;
            positive.required = amount.value === '';
        }
        [positive, negative, warning].forEach(function (control) {
            control.addEventListener('change', function () { syncAmount(control); });
        });
        function addImages(files) {
            Array.from(files).forEach(function (file) {
                if (!file.type.startsWith('image/')) return;
                if (images.length >= MAX_SCREENSHOTS || file.size > MAX_SCREENSHOT_BYTES) {
                    notify('Можно добавить до 6 изображений размером не более 5 МБ каждое.');
                    return;
                }
                var entry = { file: file };
                images.push(entry);
                var item = document.createElement('div');
                item.className = 'partner-reward-image';
                var image = document.createElement('img');
                image.alt = file.name;
                var name = document.createElement('span');
                name.textContent = file.name;
                name.title = file.name;
                var remove = document.createElement('button');
                remove.type = 'button';
                remove.textContent = '×';
                remove.setAttribute('aria-label', 'Убрать ' + file.name);
                remove.addEventListener('click', function () {
                    images = images.filter(function (candidate) { return candidate !== entry; });
                    item.remove();
                });
                item.append(image, name, remove);
                attachments.appendChild(item);
                var reader = new FileReader();
                reader.onload = function () { if (images.includes(entry)) image.src = reader.result; };
                reader.onerror = function () {
                    if (!images.includes(entry)) return;
                    images = images.filter(function (candidate) { return candidate !== entry; });
                    item.remove();
                    notify('Не удалось прочитать изображение. Попробуйте другой файл.');
                };
                reader.readAsDataURL(file);
            });
        }
        filesInput.addEventListener('change', function () {
            addImages(filesInput.files);
            filesInput.value = '';
        });
        reason.addEventListener('paste', function (event) {
            var imagesToPaste = Array.from(event.clipboardData.items).filter(function (item) {
                return item.kind === 'file' && item.type.startsWith('image/');
            }).map(function (item) { return item.getAsFile(); }).filter(Boolean);
            if (imagesToPaste.length) {
                event.preventDefault();
                addImages(imagesToPaste);
            }
        });
        reason.addEventListener('input', function () { reason.setCustomValidity(''); });
        form.addEventListener('submit', function (event) {
            event.preventDefault();
            var choiceCount = (positive.value !== '' ? 1 : 0) + (negative.value !== '' ? 1 : 0) + (warning.checked ? 1 : 0);
            if (choiceCount !== 1) {
                notify('Выберите одно действие: поощрение, депремирование или предупреждение.');
                return;
            }
            syncAmount();
            reason.setCustomValidity(reason.value.trim() ? '' : 'Укажите причину');
            var validDirection = warning.checked ? amount.value === '0.00' : amount.value !== '0.00' &&
                (negative.value !== '' ? amount.value.charAt(0) === '-' : amount.value.charAt(0) !== '-');
            if (!form.reportValidity() || !IS_PREVIEW || !validDirection || !ALLOWED_AMOUNTS.includes(amount.value)) return;
            var payload = {
                partner_id: partner.value, amount_credits: amount.value, unit: 'credits',
                action: amount.value === '0.00' ? 'warning' : amount.value.charAt(0) === '-' ? 'penalty' : 'reward',
                reason: reason.value.trim(), screenshots: images.map(function (entry) { return entry.file; })
            };
            // Informational demo event only. A production adapter must implement authorization and confirmation.
            form.dispatchEvent(new CustomEvent('admin:partneradjustmentpreview', { bubbles: true, detail: payload }));
            window.jQuery(modal).modal('hide');
            notify('Демо: действие для ' + partner.selectedOptions[0].textContent + ' подготовлено. Баланс не изменён, запрос не отправлен.');
        });
        window.jQuery(modal).on('show.bs.modal', function (event) {
            reset();
            var trigger = event.relatedTarget;
            if (trigger) partner.value = trigger.getAttribute('data-partner-id');
        }).on('hidden.bs.modal', reset);
    }
    function initPartner() {
        initReward();
        // The legacy value is MAX(transaction.created_at), not an external-transfer event.
        document.querySelectorAll('table thead tr:first-child th').forEach(function (heading) {
            var source = heading.getAttribute('data-partner-payout-source');
            if (source || heading.textContent.trim() === 'Last Payout') {
                heading.textContent = source === 'confirmed_external' ? 'Последняя выплата' : 'Последняя операция';
                heading.setAttribute('data-partner-payout-source', source === 'confirmed_external' ? source : 'legacy_operation');
            }
        });
        // PartnerSearch.role exists but is neither safe nor applied in the pinned backend.
        document.querySelectorAll('[name="PartnerSearch[role]"]').forEach(function (select) {
            if (!IS_PREVIEW && select.getAttribute('data-filter-ready') !== 'true') {
                select.disabled = true;
                select.title = 'Фильтр роли требует подключения PartnerSearch';
            }
        });
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initPartner);
    else initPartner();
    if (window.jQuery) window.jQuery(document).on('pjax:end.partnerContext', initPartner);
}());

